commands.command:
$t = Join-Path $env:TEMP "ops-jitter-check"; Remove-Item -Recurse -Force $t -ErrorAction SilentlyContinue; New-Item -ItemType Directory $t | Out-Null; Copy-Item -Recurse src,test,package.json $t; Push-Location $t
$checks = @(
"node --input-type=module -e `"import { backoffDelays } from './src/retry.mjs'; import assert from 'node:assert/strict'; assert.deepEqual(backoffDelays(3, 100, () => 0), [50, 100, 200]); assert.deepEqual(backoffDelays(3, 100, () => 0.5), [75, 150, 300]);`"",
"node --input-type=module -e `"import { backoffDelays } from './src/retry.mjs'; import assert from 'node:assert/strict'; for (let n = 0; n < 1000; n++) { const d = backoffDelays(6, 100); assert.equal(d.length, 6); d.forEach((v, i) => { const e = 100 * 2 ** i; assert.ok(v >= e / 2 && v <= e, 'delay ' + i + ' out of range: ' + v); }); }`"",
"node --input-type=module -e `"import { backoffDelays } from './src/retry.mjs'; import assert from 'node:assert/strict'; assert.deepEqual(backoffDelays(0, 100), []);`""
)
"--- current code ---"; foreach ($c in $checks) { Invoke-Expression $c 2>$null | Out-Null; "exit $LASTEXITCODE" }
Set-Content src/retry.mjs "export function backoffDelays(attempts, baseMs, random = Math.random) { return Array.from({ length: attempts }, (_, i) => { const e = baseMs * 2 ** i; return e / 2 + random() * (e / 2); }); }"
"--- scratch jitter ---"; foreach ($c in $checks) { Invoke-Expression $c 2>&1 | Out-Host; "exit $LASTEXITCODE" }
Pop-Location; Remove-Item -Recurse -Force $t; git status --porcelain
